import { requireUser } from '../auth.js';
import { config } from '../../config.js';
import { readMultipart, saveImage, deleteUpload } from '../files.js';
import { withStats, publicBank } from '../../services/serialize.js';
import { createOrder, preCheckNumbers, ApiError } from '../../services/orders.js';
import { notifyAdminsNewOrder } from '../../bot/index.js';
import { Lottery, BankAccount, Order, Ticket, Notification } from '../../models/index.js';

const activeFilter = () => ({ status: 'ACTIVE', endsAt: { $gt: new Date() } });

export default async function publicRoutes(app) {
  app.addHook('preHandler', requireUser);

  // ---- who am I ----
  app.get('/me', async (req) => {
    const u = req.user;
    const unread = await Notification.countDocuments({ user: u.telegramId, read: false });
    return {
      id: u.telegramId,
      firstName: u.firstName,
      username: u.username,
      language: u.language || 'en',
      phone: u.phone,
      isAdmin: req.isAdmin,
      botUsername: config.botUsername,
      unread,
    };
  });

  app.patch('/me', async (req, reply) => {
    const { language } = req.body || {};
    if (!['om', 'am', 'en'].includes(language)) return reply.code(400).send({ error: 'bad_language' });
    req.user.language = language;
    await req.user.save();
    return { ok: true };
  });

  // ---- home ----
  app.get('/home', async () => {
    const list = await withStats(await Lottery.find(activeFilter()).sort({ createdAt: -1 }));
    // featured = newest lottery flagged featured, otherwise the newest one
    const featured = list.find((l) => l.featured) || list[0] || null;
    const others = list.filter((l) => l.id !== featured?.id);
    return { featured, others };
  });

  // ---- one lottery (+ list of unavailable numbers) ----
  app.get('/lotteries/:id', async (req, reply) => {
    if (!/^[a-f\d]{24}$/i.test(req.params.id)) return reply.code(404).send({ error: 'not_found' });
    const lottery = await Lottery.findById(req.params.id);
    if (!lottery) return reply.code(404).send({ error: 'not_found' });
    const taken = (await Ticket.find({ lottery: lottery._id }).select('number -_id'))
      .map((t) => t.number)
      .sort((a, b) => a - b);
    return {
      lottery: await withStats(lottery),
      taken,
      open: lottery.status === 'ACTIVE' && lottery.endsAt > new Date(),
    };
  });

  // ---- bank accounts (managed by admin) ----
  app.get('/banks', async () => {
    const rows = await BankAccount.find({ active: true }).sort({ sortOrder: 1, _id: 1 });
    return rows.map(publicBank);
  });

  // ---- submit an order ----
  app.post('/orders', async (req, reply) => {
    const { fields, file } = await readMultipart(req);

    const lotteryId = String(fields.lotteryId || '');
    if (!/^[a-f\d]{24}$/i.test(lotteryId)) throw new ApiError(400, 'bad_lottery');
    const lottery = await Lottery.findById(lotteryId);
    if (!lottery) throw new ApiError(404, 'not_found');
    if (lottery.status !== 'ACTIVE' || lottery.endsAt <= new Date()) throw new ApiError(409, 'lottery_closed');

    let numbers;
    try {
      numbers = JSON.parse(fields.numbers);
    } catch {
      throw new ApiError(400, 'bad_numbers');
    }
    if (
      !Array.isArray(numbers) ||
      numbers.length < 1 ||
      numbers.length > lottery.totalTickets ||
      !numbers.every((n) => Number.isInteger(n) && n >= 1 && n <= lottery.totalTickets) ||
      new Set(numbers).size !== numbers.length
    )
      throw new ApiError(400, 'bad_numbers');

    const fullName = String(fields.fullName || '').trim();
    if (fullName.length < 2 || fullName.length > 80) throw new ApiError(400, 'bad_name');
    if (!req.user.phone) throw new ApiError(400, 'no_phone');
    if (!file) throw new ApiError(400, 'receipt_required');

    let bankId = null;
    if (fields.bankId) {
      if (!/^[a-f\d]{24}$/i.test(fields.bankId)) throw new ApiError(400, 'bad_bank');
      const bank = await BankAccount.findById(fields.bankId);
      if (!bank) throw new ApiError(400, 'bad_bank');
      bankId = bank._id;
    }
    const senderAccount = String(fields.senderAccount || '').trim().slice(0, 40);

    numbers.sort((a, b) => a - b);
    await preCheckNumbers(lottery._id, numbers); // fast answer before saving the file

    const receiptUrl = await saveImage(file, 'receipts');
    try {
      const order = await createOrder({
        user: req.user,
        lottery,
        numbers,
        fullName,
        bankId,
        senderAccount,
        receiptUrl,
      });
            // tell the admins (does not block or break the customer's order if it fails)
      notifyAdminsNewOrder({ order, lottery, numbers, user: req.user }).catch((e) =>
        console.warn('Admin notification failed:', e.message)
      );
      return reply.code(201).send({ code: order.code, total: order.total });
    } catch (e) {
      await deleteUpload(receiptUrl);
      throw e;
    }
  });

  // ---- my orders ----
  app.get('/orders/mine', async (req) => {
    const orders = await Order.find({ user: req.user.telegramId })
      .sort({ createdAt: -1 })
      .limit(100)
      .populate('lottery', 'title carName imageUrl winnerNumber status')
      .populate('bankAccount', 'bankName');
    const tickets = await Ticket.find({ order: { $in: orders.map((o) => o._id) } }).select('order number');
    const byOrder = new Map();
    for (const t of tickets) {
      const k = String(t.order);
      if (!byOrder.has(k)) byOrder.set(k, []);
      byOrder.get(k).push(t.number);
    }
    return orders.map((o) => ({
      code: o.code,
      status: o.status,
      total: o.total,
      createdAt: o.createdAt,
      rejectReason: o.rejectReason || null,
      bank: o.bankAccount?.bankName || null,
      lottery: o.lottery && {
        title: o.lottery.title,
        carName: o.lottery.carName,
        imageUrl: o.lottery.imageUrl,
        winnerNumber: o.lottery.winnerNumber ?? null,
      },
      numbers: (byOrder.get(String(o._id)) || []).sort((a, b) => a - b),
    }));
  });

  // ---- notifications (bell) ----
  app.get('/notifications', async (req) => {
    const rows = await Notification.find({ user: req.user.telegramId }).sort({ createdAt: -1 }).limit(50);
    return rows.map((n) => ({ id: String(n._id), title: n.title, body: n.body, read: n.read, createdAt: n.createdAt }));
  });

  app.post('/notifications/read', async (req) => {
    await Notification.updateMany({ user: req.user.telegramId, read: false }, { read: true });
    return { ok: true };
  });
}
